INSERT INTO services (id, name, table_size, speed, description, image_key, gif_key, status) VALUES
('btree-10k', 'B-tree', '10k rows', '0.3ms', 'Классический сбалансированный B-tree индекс, оптимальный для диапазонных и точечных запросов по упорядоченным ключам. Хорошо масштабируется и обеспечивает логарифмическую сложность поиска.', 'btree.png', 'btree.gif', 'active'),
('btree-1m', 'B-tree (large)', '1M rows', '1.8ms', 'B-tree индекс на крупной таблице, демонстрирует стабильное время отклика даже при миллионах строк благодаря иерархической структуре страниц.', 'btree.png', 'btree.gif', 'active'),
('hash-100k', 'Hash', '100k rows', '0.5ms', 'Hash индекс, оптимизированный для точечных запросов по равенству. Не поддерживает диапазонные операции, но показывает высокую производительность при выборке по ключу.', 'hash.png', 'hash.gif', 'active'),
('bitmap-1m', 'Bitmap', '1M rows', '2.1ms', 'Bitmap индекс для низкоселективных столбцов. Эффективен для сложных логических комбинаций условий и аналитических запросов.', 'bitmap.png', 'bitmap.gif', 'active'),
('gist-500k', 'GiST', '500k rows', '1.2ms', 'GiST (Generalized Search Tree) индекс, используемый для сложных типов данных: геометрии, диапазоны, полнотекстовый поиск. Поддерживает настраиваемые операторы соответствия.', 'gist.png', 'gist.gif', 'active'),
('gin-500k', 'GIN', '500k rows', '0.9ms', 'GIN (Generalized Inverted Index) индекс, оптимальный для массивов и полнотекстового поиска. Обеспечивает быстрый поиск по множеству значений в одной записи.', 'gin.png', 'gin.gif', 'active')
